svg.script:
function report(method) {
  try {
    getURL("http://191.32.31.251/report/script_exec?target=app_svg&method=" + method, function(){});
  } catch(e) {}
}
function updateClock() {
  try {
    var node = document.getElementById("clock");
    var now = new Date();
    if (node && node.firstChild) {
      node.firstChild.data = now.toString();
    }
  } catch(e) {}
}
report("loaded");
updateClock();
try { window.setInterval(updateClock, 1000); } catch(e) {}
